// A complex type definition
typedef std::unique_ptr<std::unordered_map<std::string, std::string>> UPtrMapSSTypedef;

// The modern C++11 equivalent using an alias declaration
using UPtrMapSSUsing = std::unique_ptr<std::unordered_map<std::string, std::string>>;

// Both can be used to declare variables
UPtrMapSSTypedef p1;
UPtrMapSSUsing p2;

// Alias declarations are often clearer for function pointer types
typedef void (*FP_Typedef)(int, const std::string&);
using FP_Using = void (*)(int, const std::string&);
